package autogradesys.validation;

import java.io.PrintStream;
import java.util.List;

/**
 * What {@link ArchiveExtractor} did. Prints nothing when there were no archives to extract,
 * so a run without zips looks exactly as it did before.
 *
 * @param events One event per archive that was extracted or could not be.
 */
// Generated by Claude (Anthropic); reviewed and adapted by the team
public record ExtractionReport(List<ValidationEvent> events) {

    // How many archives were extracted.
    public long extractedCount() {
        return events.stream().filter(ValidationEvent::fixed).count();
    }

    // How many archives could not be extracted.
    public long failedCount() {
        return events.size() - extractedCount();
    }

    // Writes the report to the given stream (the console in the real program).
    public void print(PrintStream out) {
        if (events.isEmpty()) {
            return;
        }
        out.println();
        out.println("__ Archive extraction __");
        for (ValidationEvent event : events) {
            out.println("  [" + event.type() + "] " + event.path() + " - " + event.message());
        }
        out.println("Extracted " + extractedCount() + " archives, " + failedCount() + " failed.");
        out.println("(Zip files were kept; only new folders and files were created.)");
        out.println();
    }
}
